  /* ---------------- water, bases, moisturizers ---------------- */
  E("water", "Water (Aqua)", ["aqua", "water", "eau", "purified water", "aqua water", "aqua eau", "demineralized water", "deionized water"], "Solvent", "Plain water. It dissolves the other ingredients and makes up most of many products.", "low", "No concern.", ["cosing"], { pen: 0 });
  E("glycerin", "Glycerin", ["glycerin", "glycerine", "glycerol", "vegetable glycerin"], "Moisturizer / humectant", "A sweet, clear liquid that pulls water into skin and keeps toothpaste from drying out.", "low", "Very well studied and considered safe as used in personal care products.", ["cir"], { good: true });
  E("sorbitol", "Sorbitol", ["sorbitol"], "Sweetener / moisturizer", "A sugar alcohol that keeps toothpaste moist and adds mild sweetness without feeding cavity bacteria like sugar does.", "low", "Safe as used. Swallowing large amounts can cause loose stools, which is not a concern from brushing.", ["cir", "ada_tooth"]);
  E("propylene_glycol", "Propylene glycol", ["propylene glycol", "propanediol", "1,2-propanediol"], "Moisturizer / solvent", "A common clear liquid that holds moisture and helps other ingredients mix.", "low", "Considered safe as used. It can irritate or cause a rash in a small number of people with sensitive skin, especially at high levels in leave-on products.", ["cir"], { pen: 1 });
  E("butylene_glycol", "Butylene glycol / pentylene glycol / caprylyl glycol", ["butylene glycol", "pentylene glycol", "caprylyl glycol", "1,2-hexanediol", "hexanediol", "propanediol", "methylpropanediol"], "Moisturizer / helps preserve", "Mild, water-loving liquids that soften skin and help the preservative work better.", "low", "Considered safe as used.", ["cir"]);
  E("cetyl_alc", "Cetyl / cetearyl / stearyl alcohol", ["cetyl alcohol", "cetearyl alcohol", "stearyl alcohol", "behenyl alcohol", "lauryl alcohol", "myristyl alcohol", "c12-15 alcohols", "c12-16 alcohols", "c14-22 alcohols"], "Thickener / softener", "Waxy 'fatty alcohols' made from plant oils. They make creams and conditioners thick and silky. They are NOT drying alcohols like rubbing alcohol.", "low", "Considered safe as used. Very rarely cause skin allergy.", ["cir"]);
  E("stearic", "Stearic / lauric / palmitic / myristic acid", ["stearic acid", "lauric acid", "palmitic acid", "myristic acid", "oleic acid", "linoleic acid", "tallow acid", "coconut acid", "palm kernel acid", "behenic acid", "caprylic acid", "capric acid", "caprylic/capric triglyceride", "caprylic capric triglyceride"], "Soap base / softener", "Natural fatty acids from plant or animal fats. They help make soap and creams.", "low", "Considered safe as used.", ["cir"]);
  E("mineral_oil", "Mineral oil / petrolatum", ["mineral oil", "paraffinum liquidum", "petrolatum", "petroleum jelly", "paraffin", "microcrystalline wax", "ozokerite", "ceresin", "isohexadecane", "hydrogenated polyisobutene", "polyisobutene", "isododecane"], "Moisturizer / sealant", "Oils and waxes refined from petroleum. They seal moisture into skin.", "low", "Highly refined grades are considered safe. Concern is about unrefined grades that can contain PAHs; EU rules require cosmetic grades to be fully refined.", ["cir", "eu_1223"], { pen: 1 });
  E("dimethicone", "Dimethicone / silicones", ["dimethicone", "amodimethicone", "dimethiconol", "dimethicone crosspolymer", "phenyl trimethicone", "trimethylsiloxysilicate", "cyclomethicone"], "Smoothing / shine", "Silicone oils that make hair slippery and shiny and skin feel silky.", "low", "Considered safe for skin and hair as used. Silicones are not biodegradable, which is an environmental rather than a personal-health question; they can build up on hair.", ["cir"], { pen: 1 });
  E("d5", "Cyclopentasiloxane (D5) / cyclotetrasiloxane (D4)", ["cyclopentasiloxane", "cyclotetrasiloxane", "cyclohexasiloxane", "d4", "d5", "d6"], "Silky carrier", "Light, fast-drying silicone liquids that make products feel smooth.", "mod", "Main concern is environmental persistence rather than skin safety. The EU restricts D4, D5 and D6 in wash-off products (REACH Regulation 2018/35). Considered safe on skin as used.", ["cosing", "cir"], { pen: 3 });
  E("shea", "Shea butter / plant butters and oils", ["butyrospermum parkii butter", "butyrospermum parkii (shea) butter", "shea butter", "theobroma cacao seed butter", "cocoa butter", "mangifera indica seed butter", "mango butter", "cocos nucifera oil", "coconut oil", "olea europaea fruit oil", "olive oil", "helianthus annuus seed oil", "sunflower seed oil", "simmondsia chinensis seed oil", "jojoba oil", "persea gratissima oil", "avocado oil", "prunus amygdalus dulcis oil", "sweet almond oil", "argania spinosa kernel oil", "argan oil", "ricinus communis seed oil", "castor oil", "hydrogenated castor oil", "hydrogenated vegetable oil", "glyceryl stearate", "glyceryl stearate se", "glyceryl caprylate", "glyceryl laurate", "squalane", "squalene", "beeswax", "cera alba", "lanolin", "copernicia cerifera cera", "carnauba wax", "sesamum indicum seed oil", "vitis vinifera seed oil", "grape seed oil"], "Moisturizer / softener", "Natural oils, butters and waxes from plants (or beeswax / lanolin from animals) that soften and seal in moisture.", "low", "Considered safe as used. Nut-based oils (e.g. sweet almond) matter only if you have a nut allergy; lanolin can rarely trigger a skin allergy.", ["cir"]);
  E("panthenol", "Panthenol (vitamin B5)", ["panthenol", "dl-panthenol", "d-panthenol", "pantothenic acid", "dexpanthenol"], "Conditioner / soother", "A form of vitamin B5 that helps skin and hair hold water and calms irritation.", "low", "Considered safe and gentle as used.", ["cir"], { good: true });
